//! Runway — how long the money lasts, and it is reported on the LOW band.
//!
//! This is the number people act on, so it is the one most worth getting pessimistic. A runway
//! computed on expected income says "eleven months" and is right on average and useless in the case
//! that matters: the case where income comes in low is exactly the case where you needed to know.
//! All three scenarios are computed; [`Runway::headline`] is `low`, and that choice is the module's
//! position rather than a default somebody can drift away from.
//!
//! # Two things that are unknown, not zero — and both would silently lengthen the runway
//!
//! 1. **Discretionary spending.** The obligation calendar knows rent and subscriptions. It does not
//!    know groceries, fuel, or a haircut. A runway from obligations alone is not conservative — it is
//!    wrong in the flattering direction. So `discretionary` is a REQUIRED argument: passing zero is
//!    allowed and is a decision that gets said out loud in the problems list.
//! 2. **Months past the calendar.** Beyond the calendar's window there are no known obligations, so
//!    costs would read as zero and the runway would extend forever on nothing. The horizon is
//!    TRUNCATED to what the calendar actually covers, and truncating is stated.
use crate::money::{money, scale, Currency, Money, Rounding};
use crate::obligations::{month_total, months_between, ObligationCalendar};
use crate::position::Position;
use crate::projection::{IncomeProjection, MonthBand};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Scenario {
    Low,
    Expected,
    High,
}

impl Scenario {
    pub fn label(self) -> &'static str {
        match self {
            Scenario::Low => "low",
            Scenario::Expected => "expected",
            Scenario::High => "high",
        }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub struct RunwayMonth {
    pub month: String,
    /// Liquid at the start of the month.
    pub opening: Money,
    pub income: Money,
    pub obligations: Money,
    pub discretionary: Money,
    /// income − obligations − discretionary.
    pub net: Money,
    pub closing: Money,
    /// POSITIVE amount the month ends short by, when it ends short.
    pub shortfall: Option<Money>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct RunwayResult {
    pub scenario: Scenario,
    pub months: Vec<RunwayMonth>,
    /// The FIRST month that ends below zero. Not the worst one — the first.
    pub exhausts_in: Option<String>,
    /// WHOLE months survived before that. None when the horizon is survived outright.
    pub months_of_cover: Option<usize>,
    /// The lowest closing balance anywhere in the horizon, which can be LATER than exhaustion.
    pub tightest: Option<RunwayMonth>,
    /// The smallest constant monthly amount that would keep every month above zero.
    pub monthly_gap: Money,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Runway {
    pub as_of: String,
    pub currency: Currency,
    /// LIQUID only. An investment is not runway, and net worth is not money you can spend.
    pub starting_liquid: Money,
    pub low: RunwayResult,
    pub expected: RunwayResult,
    pub high: RunwayResult,
    /// The one to plan on. It is `low`, deliberately.
    pub headline: RunwayResult,
    /// How far the horizon actually reaches, after truncation.
    pub through: Option<String>,
    pub problems: Vec<String>,
    pub provenance: String,
}

pub struct RunwayOptions {
    /// Everything the calendar cannot see: groceries, fuel, transport, the ordinary week. REQUIRED,
    /// so it cannot be forgotten — a runway that quietly assumes zero is the flattering kind of wrong.
    pub discretionary: Money,
}

fn band_value(b: &MonthBand, s: Scenario) -> Money {
    match s {
        Scenario::Low => b.low,
        Scenario::High => b.high,
        Scenario::Expected => b.expected,
    }
}

fn walk(months: &[&MonthBand], calendar: &ObligationCalendar, start: Money, discretionary: Money, scenario: Scenario, currency: Currency) -> RunwayResult {
    let mut out: Vec<RunwayMonth> = Vec::new();
    let mut balance = start;
    for band in months {
        let income = band_value(band, scenario);
        let obligations = month_total(calendar, &band.month, currency);
        // Every figure reaching here is already this position's currency — the caller refuses a
        // mismatched discretionary before walking, and the projection is built from one analysis.
        let net = money(income.minor - obligations.minor - discretionary.minor, currency);
        let opening = balance;
        let closing = money(opening.minor + net.minor, currency);
        balance = closing;
        out.push(RunwayMonth {
            month: band.month.clone(),
            opening,
            income,
            obligations,
            discretionary,
            net,
            closing,
            shortfall: if closing.minor < 0 { Some(money(-closing.minor, currency)) } else { None },
        });
    }

    // THE FIRST month that ends short, not the worst one. Income can be lumpy enough that a later
    // month is deeper underwater, but the month you run out of money is the month you run out.
    let first_short = out.iter().position(|m| m.closing.minor < 0);
    let tightest = out.iter().fold(None::<&RunwayMonth>, |worst, m| match worst {
        Some(w) if w.closing.minor <= m.closing.minor => Some(w),
        _ => Some(m),
    });

    // Adding x per month raises month i's closing by x·(i+1), so the smallest x that clears every
    // month is the largest per-month share of any deficit. EXACT, not searched for.
    let need = out.iter().enumerate().fold(0.0_f64, |mx: f64, (i, m)| {
        let want = if m.closing.minor < 0 { -m.closing.minor as f64 / (i + 1) as f64 } else { 0.0 };
        mx.max(want)
    });

    RunwayResult {
        scenario,
        exhausts_in: first_short.map(|i| out[i].month.clone()),
        months_of_cover: first_short,
        tightest: tightest.cloned(),
        // CEIL, because a gap rounded down does not close it.
        monthly_gap: money(need.ceil() as i64, currency),
        months: out,
    }
}

pub fn runway(position: &Position, projection: &IncomeProjection, calendar: &ObligationCalendar, opts: &RunwayOptions) -> Runway {
    let discretionary = opts.discretionary;
    let currency = position.currency;
    let mut problems: Vec<String> = position.problems.clone();

    let empty = |scenario: Scenario| RunwayResult {
        scenario,
        months: Vec::new(),
        exhausts_in: None,
        months_of_cover: None,
        tightest: None,
        monthly_gap: money(0, currency),
    };
    let refuse = |reason: String, mut problems: Vec<String>| {
        problems.push(reason);
        Runway {
            as_of: position.as_of.clone(),
            currency,
            starting_liquid: position.liquid,
            low: empty(Scenario::Low),
            expected: empty(Scenario::Expected),
            high: empty(Scenario::High),
            headline: empty(Scenario::Low),
            through: None,
            problems,
            provenance: position.provenance.clone(),
        }
    };

    if !projection.projectable {
        let r = format!("no runway without an income projection: {}", projection.reason.clone().unwrap_or_default());
        return refuse(r, problems);
    }
    if discretionary.currency != currency {
        let r = format!("discretionary spending is in {} but the position is in {}", discretionary.currency.as_str(), currency.as_str());
        return refuse(r, problems);
    }

    // TRUNCATE to what the calendar covers. Past its window there are no known obligations, so every
    // month beyond would read as costing nothing and the runway would extend on the strength of a
    // GAP IN THE DATA rather than on money.
    let covered = months_between(&calendar.from, &calendar.to);
    let months: Vec<&MonthBand> = projection.months.iter().filter(|b| covered.contains(&b.month)).collect();
    if months.len() < projection.months.len() {
        problems.push(format!(
            "the obligation calendar stops at {}, so the runway is cut to {} of {} projected month(s) — beyond it nothing is known to be due, which is not the same as nothing being due",
            calendar.to,
            months.len(),
            projection.months.len()
        ));
    }
    if months.is_empty() {
        let r = format!("the obligation calendar ({}..{}) covers none of the projected months", calendar.from, calendar.to);
        return refuse(r, problems);
    }
    if discretionary.minor == 0 {
        problems.push(
            "discretionary spending was given as zero — this runway assumes groceries, fuel and everything else outside the standing obligations cost nothing, which nobody's does".to_string(),
        );
    }
    if !position.complete {
        problems.push("the position under this runway is incomplete, so every figure here inherits whatever it could not account for".to_string());
    }

    let low = walk(&months, calendar, position.liquid, discretionary, Scenario::Low, currency);

    Runway {
        as_of: position.as_of.clone(),
        currency,
        starting_liquid: position.liquid,
        expected: walk(&months, calendar, position.liquid, discretionary, Scenario::Expected, currency),
        high: walk(&months, calendar, position.liquid, discretionary, Scenario::High, currency),
        // THE HEADLINE IS THE LOW BAND. A runway on expected income is right on average and useless
        // in the case that matters, because the case where income comes in low is the case you
        // needed it for.
        headline: low.clone(),
        low,
        through: months.last().map(|b| b.month.clone()),
        problems,
        provenance: position.provenance.clone(),
    }
}

/// Whether the horizon is survived outright under a scenario.
pub fn survives_horizon(r: &RunwayResult) -> bool {
    r.exhausts_in.is_none() && !r.months.is_empty()
}

/// What a year of the headline gap costs to close. Often the more legible framing of `monthly_gap`.
pub fn annual_gap(r: &Runway) -> Money {
    scale(r.headline.monthly_gap, 12.0, Rounding::HalfUp)
}

/// One sentence a person can act on, in the terms they asked the question in.
pub fn summarise(r: &Runway) -> String {
    let h = &r.headline;
    if h.months.is_empty() {
        let why = r.problems.last().cloned().unwrap_or_else(|| "not enough is known".to_string());
        return format!("no runway could be computed — {why}");
    }
    if survives_horizon(h) {
        let t = h.tightest.as_ref().expect("a non-empty walk always has a tightest month");
        return format!(
            "on the LOW income band the money holds through {}, tightest at {} with {} minor units left",
            r.through.clone().unwrap_or_default(),
            t.month,
            t.closing.minor
        );
    }
    format!(
        "on the LOW income band the money runs out in {} — {} whole month(s) of cover; {} minor units more per month would close it",
        h.exhausts_in.clone().unwrap_or_default(),
        h.months_of_cover.unwrap_or(0),
        h.monthly_gap.minor
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::money::usd;
    use crate::obligations::MonthTotal;
    use crate::projection::ProjectionTotal;

    // SYNTHETIC FIXTURES ONLY.
    fn band(month: &str, low: i64, expected: i64, high: i64) -> MonthBand {
        MonthBand { month: month.to_string(), low: usd(low), expected: usd(expected), high: usd(high) }
    }

    fn projection() -> IncomeProjection {
        IncomeProjection {
            projectable: true,
            reason: None,
            months: vec![band("2026-07", 300_000, 400_000, 500_000), band("2026-08", 280_000, 400_000, 520_000), band("2026-09", 260_000, 400_000, 540_000), band("2026-10", 240_000, 400_000, 560_000)],
            total: Some(ProjectionTotal { low: usd(0), expected: usd(0), high: usd(0) }),
            assumptions: Vec::new(),
            excluded: Vec::new(),
            sources_used: 1,
        }
    }

    fn calendar(to: &str, per: i64) -> ObligationCalendar {
        let by_month: Vec<MonthTotal> = ["2026-07", "2026-08", "2026-09", "2026-10"]
            .iter()
            .filter(|m| **m <= &to[..7])
            .map(|m| MonthTotal { month: m.to_string(), total: usd(per), count: 1 })
            .collect();
        ObligationCalendar { from: "2026-07-01".to_string(), to: to.to_string(), obligations: Vec::new(), by_month, heaviest: None, notes: Vec::new() }
    }

    fn position(liquid: i64, complete: bool, problems: Vec<String>) -> Position {
        Position {
            as_of: "2026-06-30".to_string(),
            currency: Currency::USD,
            accounts: Vec::new(),
            net_worth: usd(liquid),
            liquid: usd(liquid),
            total_debt: usd(0),
            daily_interest: usd(0),
            minimums_due: usd(0),
            weighted_apr: None,
            complete,
            provenance: "reconciled".to_string(),
            problems,
        }
    }

    fn opts(d: i64) -> RunwayOptions {
        RunwayOptions { discretionary: usd(d) }
    }

    #[test]
    fn a_surviving_horizon_reports_the_tightest_month_rather_than_a_date_it_runs_out() {
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(0));
        let got: Vec<(&str, i64, i64, i64, i64)> = r.low.months.iter().map(|m| (m.month.as_str(), m.opening.minor, m.income.minor, m.net.minor, m.closing.minor)).collect();
        assert_eq!(
            got,
            vec![
                ("2026-07", 500_000, 300_000, -50_000, 450_000),
                ("2026-08", 450_000, 280_000, -70_000, 380_000),
                ("2026-09", 380_000, 260_000, -90_000, 290_000),
                ("2026-10", 290_000, 240_000, -110_000, 180_000)
            ]
        );
        assert!(survives_horizon(&r.low));
        assert_eq!(r.low.exhausts_in, None);
        assert_eq!(r.low.monthly_gap.minor, 0);
        assert_eq!(r.through.as_deref(), Some("2026-10"));
        // ZERO discretionary is allowed and is SAID OUT LOUD, because a runway that quietly assumes
        // groceries are free is the flattering kind of wrong.
        assert_eq!(r.problems.len(), 1);
        assert!(r.problems[0].contains("groceries"));
        assert!(summarise(&r).starts_with("on the LOW income band the money holds through 2026-10, tightest at 2026-10 with 180000"));
    }

    #[test]
    fn the_headline_is_the_low_band_and_that_is_the_modules_position() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        // The same data on EXPECTED income needs 5000 a month; on LOW it needs 135000. A headline on
        // expected would be right on average and useless in the case that matters.
        assert_eq!(r.low.monthly_gap.minor, 135_000);
        assert_eq!(r.expected.monthly_gap.minor, 5_000);
        assert_eq!(r.headline.monthly_gap.minor, r.low.monthly_gap.minor);
        assert_eq!(r.headline.scenario, Scenario::Low);
        assert!(r.high.monthly_gap.minor < r.low.monthly_gap.minor);
    }

    #[test]
    fn the_monthly_gap_is_solved_exactly_rather_than_searched_for() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        let closings: Vec<i64> = r.low.months.iter().map(|m| m.closing.minor).collect();
        assert_eq!(closings, vec![-30_000, -180_000, -350_000, -540_000]);
        // Adding x per month raises month i by x*(i+1), so the binding constraint is the LARGEST
        // per-month share: max(30000/1, 180000/2, 350000/3, 540000/4) = 135000, from the LAST month
        // rather than the deepest ratio.
        assert_eq!(r.low.monthly_gap.minor, 135_000);
        // And it holds: 135000 a month clears every month.
        for (i, c) in closings.iter().enumerate() {
            assert!(c + 135_000 * (i as i64 + 1) >= 0, "month {i} still short");
        }
        assert_eq!(annual_gap(&r).minor, 1_620_000);
    }

    #[test]
    fn the_first_short_month_is_the_answer_not_the_worst_one() {
        let r = runway(&position(100_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &opts(80_000));
        assert_eq!(r.low.exhausts_in.as_deref(), Some("2026-07"), "the FIRST month that ends short");
        assert_eq!(r.low.months_of_cover, Some(0));
        // The TIGHTEST month is later and deeper. Both are reported because they answer different
        // questions: when do I run out, and how bad does it get.
        assert_eq!(r.low.tightest.as_ref().unwrap().month, "2026-10");
        assert_eq!(r.low.months[0].shortfall.unwrap().minor, 30_000, "the shortfall is POSITIVE");
        assert!(!survives_horizon(&r.low));
    }

    #[test]
    fn the_horizon_is_cut_to_the_calendar_and_the_cut_is_stated() {
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-08-31", 350_000), &opts(50_000));
        assert_eq!(r.low.months.len(), 2, "four months projected, two covered");
        assert_eq!(r.through.as_deref(), Some("2026-08"));
        // Without truncation the last two months would cost NOTHING and the runway would extend on
        // a gap in the data rather than on money.
        assert!(r.problems.iter().any(|p| p.contains("not the same as nothing being due")));
    }

    #[test]
    fn no_projection_is_a_refusal_that_carries_the_projections_own_reason() {
        let bad = IncomeProjection {
            projectable: false,
            reason: Some("2 whole month(s) of history; 3 are needed".to_string()),
            months: Vec::new(),
            total: None,
            assumptions: Vec::new(),
            excluded: Vec::new(),
            sources_used: 0,
        };
        let r = runway(&position(500_000, true, vec![]), &bad, &calendar("2026-10-31", 350_000), &opts(50_000));
        assert!(r.low.months.is_empty());
        assert!(!survives_horizon(&r.low), "an empty walk has not survived anything");
        assert_eq!(r.through, None);
        assert!(r.problems.last().unwrap().contains("2 whole month(s) of history"));
        assert_eq!(summarise(&r), "no runway could be computed — no runway without an income projection: 2 whole month(s) of history; 3 are needed");
    }

    #[test]
    fn a_calendar_that_does_not_overlap_the_projection_refuses_rather_than_assuming_free_months() {
        let far = ObligationCalendar { from: "2027-01-01".to_string(), to: "2027-03-31".to_string(), obligations: Vec::new(), by_month: Vec::new(), heaviest: None, notes: Vec::new() };
        let r = runway(&position(500_000, true, vec![]), &projection(), &far, &opts(50_000));
        assert!(r.low.months.is_empty());
        assert_eq!(r.problems.len(), 2, "the truncation AND the refusal are both stated");
        assert!(r.problems[1].contains("covers none of the projected months"));
    }

    #[test]
    fn an_incomplete_position_is_inherited_along_with_its_own_problems() {
        let r = runway(&position(500_000, false, vec!["a balance is stale".to_string()]), &projection(), &calendar("2026-10-31", 350_000), &opts(50_000));
        // The position's own problems come FIRST and are not replaced — a runway cannot be sounder
        // than the position under it.
        assert_eq!(r.problems[0], "a balance is stale");
        assert!(r.problems[1].contains("incomplete"));
        assert_eq!(r.low.exhausts_in.as_deref(), Some("2026-10"));
        assert_eq!(r.low.months_of_cover, Some(3));
        assert_eq!(r.low.monthly_gap.minor, 5_000);
        assert_eq!(r.provenance, "reconciled", "the provenance travels with the figure");
    }

    #[test]
    fn a_mismatched_discretionary_currency_refuses_rather_than_subtracting_it_anyway() {
        let eur = Currency::new("EUR").expect("a three-letter code");
        let r = runway(&position(500_000, true, vec![]), &projection(), &calendar("2026-10-31", 350_000), &RunwayOptions { discretionary: money(50_000, eur) });
        assert!(r.low.months.is_empty());
        assert!(r.problems.last().unwrap().contains("EUR"));
    }
}
